-- 3D backrooms. Opts out of push: g3d draws straight to the screen at native
-- resolution with the window's depth buffer, then renderHUD draws 2D on top
-- with depth testing disabled (see love.draw in main.lua).
--
-- Level sequence: the authored tutorial (BACKROOMS_ROOMS[1]), then
-- BACKROOMS_GENERATED_LEVELS levels generated by LevelGen from the run seed
-- (levelData). Reaching a level's exit loads the next; the last exit changes
-- to the ending state. `BackroomsState.roomsOverride` / enter's `rooms` swap
-- in a fixed list instead (tests).
--
-- Seed puzzles: E / Enter / left click plants the selected seed on the
-- nearest fixed plot in range (Room:nearestPlot); Q / Tab or 1-3 select the
-- seed type, among the types the current room uses (visibleSeedTypes); R
-- resets the room. Crops grow on this state's own knife Timer
-- group, which is cleared whenever a room is loaded or reset, so nothing from
-- an earlier attempt keeps growing.
BackroomsState = Class{__includes = BaseState}

BackroomsState.usesPush = false

local function anyDown(keys)
    for _, key in ipairs(keys) do
        if love.keyboard.isDown(key) then return true end
    end
    return false
end

local function anyPressed(keys)
    for _, key in ipairs(keys) do
        if love.keyboard.wasPressed(key) then return true end
    end
    return false
end

-- gameData: the carried-over table from the farm (CarryOverGameData). Only
-- seeds are read; `rooms` overrides BACKROOMS_ROOMS (tests).
function BackroomsState:enter(gameData, rooms)
    self.gameData = gameData or CarryOverGameData(NewGameData())
    self.rooms = rooms or BackroomsState.roomsOverride   -- nil: the generated sequence
    self.runSeed = BACKROOMS_RUN_SEED or math.random(1, 999999)
    self.levels = {}                     -- level index -> room data (generated once per run)
    self.levelSeeds = {}
    if not self.rooms then print('[backrooms] run seed ' .. self.runSeed) end
    self.timers = {}                     -- knife Timer group for crop growth
    self.message = nil                   -- {text, time left}
    print('[backrooms] seeds received: ' .. FormatSeeds(self.gameData.seeds))

    -- hum + footsteps live only while this state is active (see BackroomsAudio)
    if self.audio then self.audio:dispose() end
    self.audio = BackroomsAudio.new()

    g3d.camera.resize(love.graphics.getDimensions())
    self:setMouseCaptured(true)
    self.finished = false
    self.fall = nil
    Silhouette.reset()
    self.hintTime = BACKROOMS_HINT_SECONDS
    self:loadRoom(1)
end

function BackroomsState:exit()
    Silhouette.dispose()
    self.fall = nil
    Timer.clear(self.timers)
    if self.audio then self.audio:dispose(); self.audio = nil end
    if HorrorOutage then HorrorOutage.reset() end
    self:setMouseCaptured(false)
end

-- Relative mouse mode hides and locks the cursor and reports deltas through
-- love.mousemoved, which main.lua forwards to BackroomsState:mousemoved.
function BackroomsState:setMouseCaptured(captured)
    self.mouseCaptured = captured
    self.hintTime = BACKROOMS_HINT_SECONDS
    if love.mouse.setRelativeMode then love.mouse.setRelativeMode(captured) end
end

function BackroomsState:levelCount()
    return self.rooms and #self.rooms or (1 + BACKROOMS_GENERATED_LEVELS)
end

-- Room data of level `index`: the override list entry, the tutorial, or a
-- level generated from LevelGen.levelSeed(run seed, index). Cached, so a reset
-- rebuilds exactly the same level.
function BackroomsState:levelData(index)
    if self.rooms then return self.rooms[index] end
    if index == 1 then return BACKROOMS_ROOMS[1] end
    if index < 1 or index > self:levelCount() then return nil end
    local data = self.levels[index]
    if not data then
        local seed = LevelGen.levelSeed(self.runSeed, index)
        data = LevelGen.generate(seed, index - 1, {name = 'Level ' .. index})
        self.levels[index], self.levelSeeds[index] = data, seed
        print(string.format('[backrooms] level %d generated: seed %d (run seed %d), %d obstacles',
            index, seed, self.runSeed, data.meta.obstacles))
    end
    return data
end

-- Builds room `index` and places the player at its spawn. Seeds follow the
-- RoomStartingSeeds policy; the result is recorded for resetRoom.
function BackroomsState:loadRoom(index)
    local data = self:levelData(index)
    assert(data, 'no backrooms room ' .. tostring(index))
    Timer.clear(self.timers)
    self.roomIndex = index
    self.fall = nil
    Silhouette.clearActive()
    if self.audio then self.audio:setFalling(false) end
    self.room = Room(data)
    self.gameData.seeds = RoomStartingSeeds(data, index, self.gameData.seeds)
    self.roomStartSeeds = CopySeeds(self.gameData.seeds)
    self.advancing = false
    self:selectSeed(self.selectedSeed)
    self:spawnPlayer()
    self:resetCheckpoint()
    if self.audio then self.audio:reset() end
    print(string.format('[backrooms] entered room %d/%d (%s), seeds: %s',
        index, self:levelCount(), tostring(self.room.id), FormatSeeds(self.gameData.seeds)))
end

-- Checkpoints: current = region index of the latest checkpoint (0 = spawn).
function BackroomsState:resetCheckpoint()
    self.checkpointRegion, self.visitedRegions = 0, {[0] = true}
end

-- Called each frame: entering a region not yet visited makes its checkpoint current.
function BackroomsState:updateCheckpoint()
    local r = self.room:regionAt(self.player.x, self.player.y)
    if r and not self.visitedRegions[r] and self.room.checkpoints[r + 1] then
        self.visitedRegions[r] = true
        self.checkpointRegion = r
    end
end

-- Moves the player to the current checkpoint (the spawn when none); crops,
-- seeds and pickups are untouched.
function BackroomsState:respawnAtCheckpoint()
    local cp = self.room.checkpoints[(self.checkpointRegion or 0) + 1]
    if not cp then return self:spawnPlayer() end
    self.player:setPosition(cp[1], cp[2], cp[3])
    if self.audio then self.audio:reset() end
    local ex, ey, ez = self.player:eyePosition()
    g3d.camera.lookInDirection(ex, ey, ez, cp[4] or 0, 0)
end

function BackroomsState:spawnPlayer()
    local s = self.room.spawn
    if self.player then
        self.player:setPosition(s[1], s[2], s[3])
    else
        self.player = PlayerController(s[1], s[2], s[3])
    end
    local ex, ey, ez = self.player:eyePosition()
    -- lookInDirection, not lookAt: g3d's lookAt derives yaw/pitch with a y-up
    -- formula that does not match lookInDirection/firstPersonLook (z-up)
    g3d.camera.lookInDirection(ex, ey, ez, s[4] or 0, 0)
end

-- Rebuilds the current room from the same data (the same seed for a generated
-- level: layout equal, pickups respawned) and restores the seeds recorded on
-- entering it. For Room 1 that is the topped-up farm seeds; for generated
-- levels zero; for other rooms the fixed allotment. Every crop is removed, pending growth is cancelled, demo crops
-- are rebuilt at their starting growth and the player returns to the spawn.
-- Bound to BACKROOMS_KEYS.reset.
function BackroomsState:resetRoom()
    Timer.clear(self.timers)
    self.room = Room(self:levelData(self.roomIndex))
    self.gameData.seeds = CopySeeds(self.roomStartSeeds)
    self.advancing = false
    self:selectSeed(self.selectedSeed)
    self:spawnPlayer()
    self:resetCheckpoint()
    self:say('Room reset')
end

-- Seed selection --------------------------------------------------------------

-- The seed types the current room uses: its `seedTypes` list when it has one
-- (generated levels start with no seeds), else those with an allotment above
-- zero, in SEED_TYPES order. The HUD lists only these and the seed keys only select
-- these. Other types are still counted in gameData.seeds (carry-over and
-- reset are unchanged); they just cannot be used here.
function BackroomsState:visibleSeedTypes()
    local list = {}
    local allotment = self.room and self.room.allotment or {}
    local declared = {}
    for _, t in ipairs(self.room and self.room.seedTypes or {}) do declared[t] = true end
    local useDeclared = self.room and self.room.seedTypes ~= nil
    for _, t in ipairs(SEED_TYPES) do
        if (useDeclared and declared[t]) or (not useDeclared and (allotment[t] or 0) > 0) then
            list[#list + 1] = t
        end
    end
    return list
end

function BackroomsState:isSeedVisible(seedType)
    for _, t in ipairs(self:visibleSeedTypes()) do
        if t == seedType then return true end
    end
    return false
end

-- Selects `seedType` if it is visible and the player has one; otherwise the
-- first visible type they do have; otherwise keeps `seedType` if visible (or
-- the first visible type) so the HUD still shows a selection.
function BackroomsState:selectSeed(seedType)
    local seeds = self.gameData.seeds
    local visible = self:visibleSeedTypes()
    if seedType and self:isSeedVisible(seedType) and (seeds[seedType] or 0) > 0 then
        self.selectedSeed = seedType
        return
    end
    for _, t in ipairs(visible) do
        if (seeds[t] or 0) > 0 then self.selectedSeed = t; return end
    end
    if seedType and self:isSeedVisible(seedType) then
        self.selectedSeed = seedType
    else
        self.selectedSeed = visible[1] or seedType or SEED_TYPES[1]
    end
end

-- Next visible type (in SEED_TYPES order, wrapping) that the player holds.
function BackroomsState:cycleSeed()
    local visible = self:visibleSeedTypes()
    local start = 0
    for i, t in ipairs(visible) do if t == self.selectedSeed then start = i end end
    for k = 1, #visible do
        local t = visible[(start + k - 1) % #visible + 1]
        if (self.gameData.seeds[t] or 0) > 0 then self.selectedSeed = t; return end
    end
end

-- Mouse wheel: steps the selection one visible slot per notch (dir > 0 = next),
-- wrapping; only while the mouse is captured. Types the room does not use are skipped.
function BackroomsState:wheelSelect(dir)
    if not self.mouseCaptured or dir == 0 then return end
    local visible = self:visibleSeedTypes()
    local n = #visible
    if n == 0 then return end
    local cur = 0
    for i, t in ipairs(visible) do if t == self.selectedSeed then cur = i end end
    local step = dir > 0 and 1 or -1
    self.selectedSeed = visible[(cur - 1 + step) % n + 1]
end

-- Collects the pickup the player stands near, if any: +1 seed, message.
-- Returns the pickup or nil.
function BackroomsState:collectPickups()
    local p = self.room:collectPickup(self.player.x, self.player.y, self.player.z)
    if not p then return nil end
    local seeds = self.gameData.seeds
    seeds[p.seed] = (seeds[p.seed] or 0) + 1
    if gSounds['plant'] then gSounds['plant']:play() end
    self:say(string.format('Picked up a %s seed (x%d)', SeedName(p.seed), seeds[p.seed]))
    if (seeds[self.selectedSeed] or 0) == 0 then self:selectSeed(p.seed) end
    print(string.format('[backrooms] picked up %s (%s), seeds: %s', p.seed, p.tier, FormatSeeds(seeds)))
    return p
end

function BackroomsState:say(text)
    self.message = {text = text, time = 2.5}
end

-- Planting --------------------------------------------------------------------

-- The plot the player could plant on right now, or nil.
function BackroomsState:targetPlot()
    return self.room:nearestPlot(self.player.x, self.player.y, self.player.z)
end

local PLANT_MESSAGES = {
    ['no-plot'] = 'Seeds only take on the soil plots',
    ['no-seeds'] = 'No %s seeds left',
    ['occupied'] = 'Something is already growing here',
    ['growing'] = 'Something is already growing here',
    ['wrong-seed'] = 'This %s needs a %s seed',
}

-- Plants the selected seed on the nearest plot. Returns ok, crop-or-reason.
function BackroomsState:plant()
    local plot = self:targetPlot()
    local seedType = self.selectedSeed
    local ok, result = self.room:plant(plot, seedType, self.gameData.seeds, self.timers)
    if ok then
        gSounds['plant']:play()
        self:say(result.demo and ('The ' .. SeedName(seedType) .. ' keeps growing...') or ('Planted a ' .. SeedName(seedType)))
        print(string.format('[backrooms] planted %s on plot %s, seeds: %s',
            seedType, plot.id, FormatSeeds(self.gameData.seeds)))
        if (self.gameData.seeds[seedType] or 0) == 0 then self:selectSeed(seedType) end
    else
        gSounds['deny']:play()
        local fmt = PLANT_MESSAGES[result] or result
        if result == 'wrong-seed' then
            self:say(string.format(fmt, SeedName(plot.crop.type), SeedName(plot.crop.type)))
        else
            self:say(string.format(fmt, SeedName(seedType)))
        end
    end
    return ok, result
end

local UPROOT_MESSAGES = {
    ['no-plot'] = 'Nothing to uproot here',
    ['empty'] = 'Nothing to uproot here',
    ['demo'] = "This one is part of the lesson. It can't be uprooted",
    ['standing'] = 'Step off it first. You are on or in the crop',
}

-- Uproots the crop on the nearest plot with one and refunds one seed of its
-- type (grown or growing; refusals refund nothing).
-- Returns ok, crop-or-reason.
function BackroomsState:uproot()
    local plot = self.room:nearestCropPlot(self.player.x, self.player.y, self.player.z)
    local pmin, pmax = self.player:bounds()
    local ok, result = self.room:uproot(plot, pmin, pmax)
    if ok then
        if gSounds['harvest'] then gSounds['harvest']:play() end
        local seeds = self.gameData.seeds
        seeds[result.type] = (seeds[result.type] or 0) + 1
        if (seeds[self.selectedSeed] or 0) == 0 then self:selectSeed(result.type) end
        self:say(string.format('Uprooted the %s. Seed returned (x%d)', SeedName(result.type), seeds[result.type]))
        print(string.format('[backrooms] uprooted %s on plot %s, seeds: %s', result.type, plot.id, FormatSeeds(seeds)))
    else
        if gSounds['deny'] then gSounds['deny']:play() end
        self:say(UPROOT_MESSAGES[result] or result)
    end
    return ok, result
end

-- The current room is done: load the next one, or show the ending.
function BackroomsState:advance()
    if self.advancing or self.finished then return end
    self.advancing = true
    if self.roomIndex < self:levelCount() then
        self:loadRoom(self.roomIndex + 1)
    else
        self.finished = true
        gStateMachine:change('ending', {gameData = self.gameData, runSeed = self.runSeed})
    end
end

function BackroomsState:mousemoved(x, y, dx, dy)
    if self.mouseCaptured and not self.fall then
        g3d.camera.firstPersonLook(dx, dy)
    end
end

function BackroomsState:movementInput()
    local f, s = 0, 0
    if anyDown(BACKROOMS_KEYS.forward) then f = f + 1 end
    if anyDown(BACKROOMS_KEYS.back) then f = f - 1 end
    if anyDown(BACKROOMS_KEYS.right) then s = s + 1 end
    if anyDown(BACKROOMS_KEYS.left) then s = s - 1 end
    return {forward = f, strafe = s}
end

-- Pit death: fade to black (physics keeps running, controls locked), respawn
-- at the same checkpoint at full black, then fade back in. The state is reset
-- by loadRoom/resetRoom/enter/exit so it can never get stuck.
function BackroomsState:updateFall(dt)
    local f = self.fall
    if not f then
        if self.player.z < self.room.killZ then
            self.fall = {t = 0, phase = 'out', alpha = 0}
            if self.audio then self.audio:setFalling(true); self.audio:playFall() end
        end
        return
    end
    f.t = f.t + dt
    if f.phase == 'out' then
        f.alpha = math.min(1, f.t / BACKROOMS_FALL_FADE_OUT)
        if f.t >= BACKROOMS_FALL_FADE_OUT then
            self:respawnAtCheckpoint()
            f.phase, f.t, f.alpha = 'in', 0, 1
            if self.audio then self.audio:setFalling(false) end
        end
    else
        f.alpha = 1 - math.min(1, f.t / BACKROOMS_FALL_FADE_IN)
        if f.t >= BACKROOMS_FALL_FADE_IN then self.fall = nil end
    end
end

function BackroomsState:update(dt)
    -- Delete (Mac "delete" is backspace) jumps straight to the ending screen.
    if (love.keyboard.wasPressed('delete') or love.keyboard.wasPressed('backspace'))
        and not self.finished then
        self.finished = true
        gStateMachine:change('ending', {gameData = self.gameData, runSeed = self.runSeed})
        return
    end
    if IsDebugAdvancePressed() and not self.fall then
        self:advance()
        return
    end

    local clickPlants, clickUproots = false, false
    local locked = self.fall ~= nil -- controls locked for the whole pit-death transition
    if self.mouseCaptured and not locked and love.mouse.wasPressed(BACKROOMS_KEYS.uprootMouse) then clickUproots = true end
    if self.mouseCaptured and anyPressed(BACKROOMS_KEYS.releaseMouse) then
        self:setMouseCaptured(false)
    elseif not self.mouseCaptured and love.mouse.wasPressed(1) then
        self:setMouseCaptured(true)
    elseif self.mouseCaptured and not locked and love.mouse.wasPressed(1) then
        clickPlants = true
    end

    if anyPressed(BACKROOMS_KEYS.reset) and not locked then
        self:resetRoom()
        return
    end
    -- key i always means SEED_TYPES[i]; keys for types this room hides do nothing
    for i, key in ipairs(BACKROOMS_KEYS.seedSlots) do
        if locked then break end
        local t = SEED_TYPES[i]
        if love.keyboard.wasPressed(key) and t and self:isSeedVisible(t) then self.selectedSeed = t end
    end
    if not locked and anyPressed(BACKROOMS_KEYS.nextSeed) then self:cycleSeed() end
    local wheel = love.mouse.wheelDelta or 0
    if wheel ~= 0 and not locked then self:wheelSelect(wheel) end
    if self.mouseCaptured and self.hintTime > 0 then self.hintTime = self.hintTime - dt end
    if not locked and (clickPlants or anyPressed(BACKROOMS_KEYS.plant)) then self:plant() end
    if not locked and (clickUproots or anyPressed(BACKROOMS_KEYS.uproot)) then self:uproot() end

    if self.message then
        self.message.time = self.message.time - dt
        if self.message.time <= 0 then self.message = nil end
    end

    -- growth, then crops that finished growing take effect (once the player
    -- is clear of them), then the player moves against this frame's world
    Timer.update(dt, self.timers)
    local bmin, bmax = self.player:bounds()
    self.room:updateCrops(bmin, bmax)

    local direction, pitch = g3d.camera.getDirectionPitch()
    local input = self.fall and {forward = 0, strafe = 0} or self:movementInput()
    self.player:update(dt, input, direction, self.room:solidColliders(), self.room:climbVolumes())

    if self.audio then self.audio:update(dt, self.player) end

    do -- idle vignette bookkeeping (visual only)
        local px, py, pz = self.player.x, self.player.y, self.player.z or 0
        local l = self.lastPos
        if not l or math.abs(px - l[1]) + math.abs(py - l[2]) + math.abs(pz - l[3]) > 1e-3 then
            self.stillTime = 0
        else
            self.stillTime = (self.stillTime or 0) + dt
        end
        self.lastPos = {px, py, pz}
        BackroomsLook.updateIdle(dt, BackroomsLook.forceStill or self.stillTime)
    end

    Silhouette.update(dt, self.room, self.player, direction, self.fall ~= nil, pitch)
    self:updateFall(dt)
    if not self.fall then self:updateCheckpoint() end

    local ex, ey, ez = self.player:eyePosition()
    g3d.camera.lookInDirection(ex, ey, ez)

    while self:collectPickups() do end

    local pmin, pmax = self.player:bounds()
    if not self.fall and self.room:overlapsExit(pmin, pmax) then
        self:advance()
    end
end

function BackroomsState:render()
    BackroomsLook.renderScene(function()
        self.room:draw(self.player.x, self.player.y)
        Silhouette.draw(self.player.x, self.player.y)
    end)
end

-- Text with a dark outline so it reads on bright and dark walls without a band.
local function shadowPrintf(text, y, w, alpha)
    love.graphics.setColor(0, 0, 0, 0.85 * alpha)
    love.graphics.printf(text, 1, y + 1, w, 'center')
    love.graphics.setColor(1, 1, 1, alpha)
    love.graphics.printf(text, 0, y, w, 'center')
end

function BackroomsState:renderHUD()
    self:renderHUDContents()
    -- death fade drawn last, above the world and the HUD
    if self.fall and self.fall.alpha > 0 then
        local w, h = love.graphics.getDimensions()
        love.graphics.push('all')
        love.graphics.origin()
        love.graphics.setScissor()
        love.graphics.setShader()
        love.graphics.setBlendMode('alpha')
        love.graphics.setColor(0, 0, 0, self.fall.alpha)
        love.graphics.rectangle('fill', 0, 0, w, h)
        love.graphics.pop()
    end
end

function BackroomsState:renderHUDContents()
    -- HUD lives over the centred 4:3 picture, not the blurred side fill
    local ww, wh = love.graphics.getDimensions()
    local ox, oy, w, h = BackroomsLook.viewRect(ww, wh)
    love.graphics.push()
    love.graphics.translate(ox, oy)
    self:drawHUDIn(w, h)
    love.graphics.pop()
end

function BackroomsState:drawHUDIn(w, h)
    local font = gFonts['default']
    love.graphics.setFont(font)

    -- compact room-name plate (top left), no full-width band
    local title = string.format('%s  (%d/%d)', self.room.name, self.roomIndex, self:levelCount())
    love.graphics.setColor(0, 0, 0, 0.4)
    love.graphics.rectangle('fill', 8, 8, font:getWidth(title) + 16, font:getHeight() + 8, 4, 4)
    love.graphics.setColor(1, 1, 1, 1)
    love.graphics.print(title, 16, 12)

    Hotbar.draw(w, h, self.gameData.seeds, self.selectedSeed, function(t) return self:isSeedVisible(t) end)
    love.graphics.setFont(font)

    local plot = self:targetPlot()
    if plot then
        local ok, reason = self.room:canPlant(plot, self.selectedSeed, self.gameData.seeds)
        local prompt
        if ok then prompt = 'E / click: plant ' .. SeedName(self.selectedSeed)
        elseif reason == 'wrong-seed' then
            prompt = 'This ' .. SeedName(plot.crop.type) .. ' needs a ' .. SeedName(plot.crop.type) .. ' seed'
        elseif reason == 'no-seeds' then prompt = 'No ' .. SeedName(self.selectedSeed) .. ' seeds (Q: switch)'
        else prompt = 'Plot in use' end
        shadowPrintf(prompt, h / 2 + 24, w, 1)
    end
    if self.message then
        shadowPrintf(self.message.text, h / 2 + 48, w, 1)
    end

    -- controls hint: fades after BACKROOMS_HINT_SECONDS with the mouse captured;
    -- always shown while the mouse is free. Sits above the hotbar.
    local alpha = 1
    if self.mouseCaptured then
        alpha = math.max(0, math.min(1, self.hintTime / BACKROOMS_HINT_FADE))
    end
    if alpha > 0 then
        local hints = self.mouseCaptured
            and {'WASD move | Mouse look | LMB/E plant | RMB/X uproot', 'Wheel/1-3 seed | R reset | Esc mouse'}
            or {'Click to capture the mouse'}
        local lay = Hotbar.layout(w, h, #SEED_TYPES)
        -- computed block height from wrapped line counts, stacked upward from the hotbar
        local lineH = font:getHeight() + 2
        local rows = {}
        for _, line in ipairs(hints) do
            local _, wrapped = font:getWrap(line, w - 20)
            rows[#rows + 1] = {line, #wrapped}
        end
        local y = lay.y - 10
        for i = #rows, 1, -1 do
            y = y - rows[i][2] * lineH
            shadowPrintf(rows[i][1], y, w, alpha)
        end
    end
    if DEBUG_MODE then
        love.graphics.print(DEBUG_ADVANCE_KEY .. ': debug skip room   fps: ' .. love.timer.getFPS(), 10, h - 26)
    end
end
